import json, sys, math
A = json.load(open(sys.argv[1]))
rows = A['rows']; raw = A['raw']
P = json.load(open(sys.argv[2]))
setpoint = P['setpoint']

by = {r['sample']: r for r in rows}

# 1) raw export overrides transcriptions (SOP §1)
for samp, rr in raw.items():
    r = by[samp]
    if abs(r['v'] - rr['v']) > 1e-9 * max(1, rr['v']):
        print(f"RAW OVERRIDE {samp} {r['src']} {r['v']:.6g} -> {rr['v']:.6g}")
    r['v'] = rr['v']
    r['raw'] = True

# 2) label corrections / swapped substrate tubes (author addenda)
by['PX-0778']['S'] = 4.0      # 4000 nM; Lin Qiao addendum 2031-10-23
by['PX-0783']['S'] = 600.0    # 6E+05 nM; swapped tubes

# 3) exclusions
excl = {}
for r in rows:
    if r.get('T') is not None:
        if abs(r['T'] - setpoint[r['cond']]) > 1.0:
            excl[r['sample']] = 'temperature'
manual = {
    'PX-0766': 'bubble during read (D2 comment: removed 6 min into 12 min read)',
    'PX-0672': 'bubble 2 min after read start (Owen Achterberg confirmed, D8)',
    'PX-0691': 'bubble present during read (Nadia Kowalczyk correction, D8)',
    'PX-0466': 'bubble during read (D12, bubble came up before last cycle)',
    'PX-0451': 'OVR (Owen addendum, D2)',
    'PX-0817': 'OVR (Owen Achterberg chat 2031-10-22, D8)',
    'PX-0513': 'tip came off during enzyme dispense (Hamid Rostami addendum, D7)',
    'PX-0856': 'spill (Leila Haddad correction of PX-0851, D8)',
}
for k, why in manual.items():
    assert k in by, k
    excl[k] = why
# 4) sharing-check: did D2/D5 excluded for temperature list only PX-0593?
for k, why in sorted(excl.items()):
    print('EXCL', k, by[k]['cond'], why)

# 5) enzyme dilution rescale (SOP §5): C5 was made at 1:1000 (MM-12) -> ×2
for r in rows:
    if r['cond'] == 'C5':
        r['v'] *= 2.0

keep = {}
for r in rows:
    if r['sample'] in excl: continue
    keep.setdefault(r['cond'], []).append((r['sample'], r['S'], r['v']))

json.dump(dict(keep=keep, excl=excl), open(sys.argv[3], 'w'), indent=0)
for c in sorted(keep):
    print(c, len(keep[c]))

import json, sys, math
K = json.load(open(sys.argv[1]))['keep']

def sse_full(Km, pts):
    # profile: optimal Vmax for given Km (linear least squares)
    num = sum(v * S / (Km + S) for _, S, v in pts)
    den = sum((S / (Km + S)) ** 2 for _, S, v in pts)
    Vm = num / den
    s = sum((v - Vm * S / (Km + S)) ** 2 for _, S, v in pts)
    return s, Vm

def sse_km_only(Km, pts, Vfix):
    return sum((v - Vfix * S / (Km + S)) ** 2 for _, S, v in pts)

def golden(f, a, b, it=300):
    g = (math.sqrt(5) - 1) / 2
    c = b - g * (b - a); d = a + g * (b - a)
    fc, fd = f(c), f(d)
    for _ in range(it):
        if fc < fd: b, d, fd = d, c, fc; c = b - g * (b - a); fc = f(c)
        else: a, c, fc = c, d, fd; d = a + g * (b - a); fd = f(d)
    return (a + b) / 2

def fit_full(pts):
    # minimise over log Km with a fine grid first to avoid local issues
    grid = [10 ** (x / 200) for x in range(-200, 800)]
    best = min(grid, key=lambda k: sse_full(k, pts)[0])
    km = golden(lambda lk: sse_full(math.exp(lk), pts)[0], math.log(best / 1.05), math.log(best * 1.05))
    km = math.exp(km)
    s, Vm = sse_full(km, pts)
    return Vm, km, s

res = {}
for c in ['C2', 'C4', 'C5', 'C6', 'C7']:
    res[c] = fit_full(K[c])
# MPX-9 conditions: Vmax shared from matching no-inhibitor condition
share = {'C1': 'C4', 'C3': 'C6'}
for c, base in share.items():
    Vfix = res[base][0]
    grid = [10 ** (x / 200) for x in range(-200, 800)]
    best = min(grid, key=lambda k: sse_km_only(k, K[c], Vfix))
    km = math.exp(golden(lambda lk: sse_km_only(math.exp(lk), K[c], Vfix), math.log(best / 1.05), math.log(best * 1.05)))
    res[c] = (Vfix, km, sse_km_only(km, K[c], Vfix))

for c in sorted(res):
    Vm, km, s = res[c]
    print(f"{c}: Vmax={Vm:.5f} uM/s  Km={km:.3f} uM  SSE={s:.3e}  n={len(K[c])}")
json.dump({c: dict(vmax=res[c][0], km=res[c][1]) for c in res}, open(sys.argv[2], 'w'), indent=1)

